package com.agriconnect.order;import static org.assertj.core.api.Assertions.*;import java.util.*;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.*;import org.springframework.jdbc.core.simple.JdbcClient;
class ShipmentEventConsumerTest{@Test void duplicateDeliveryEventIsProcessedOnce(){JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:shipmentconsumer;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");JdbcTemplate j=new JdbcTemplate(ds);j.execute("create table orders(id bigint primary key,status varchar(20),return_state varchar(30))");j.execute("create table processed_events(event_id uuid primary key,processed_at timestamp default current_timestamp)");j.update("insert into orders values(10,'SHIPPING',null)");ShipmentEventConsumer c=new ShipmentEventConsumer(JdbcClient.create(ds));UUID id=UUID.randomUUID();Map<String,Object>event=Map.of("eventId",id,"eventType","ShipmentDelivered","payload",Map.of("orderId",10));c.consume(event);c.consume(event);assertThat(j.queryForObject("select status from orders where id=10",String.class)).isEqualTo("DELIVERED");assertThat(j.queryForObject("select count(*) from processed_events",Integer.class)).isEqualTo(1);}}
